import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";

const machine: GitProbe = {
  exists: existsSync,
  developerDir() {
    // Without DEVELOPER_DIR, which overrides the answer and which a repository's environment could set.
    const selected = spawnSync("/usr/bin/xcode-select", ["-p"], { encoding: "utf8", env: { PATH: "/usr/bin:/bin" } });
    return selected.status === 0 ? selected.stdout.trim() : undefined;
  },
};

export function gitInstalled(path: string, platform: NodeJS.Platform = process.platform, probe: GitProbe = machine): boolean {
  if (!probe.exists(path)) return false;
  if (platform !== "darwin" || path !== "/usr/bin/git") return true;
  return probe.exists("/Library/Developer/CommandLineTools/usr/bin/git");
}

import { spawnSync } from "node:child_process";

/** Every Git process Rerail starts: no optional locks, no lazy fetch of a partial clone's missing objects, no prompts. */
const GIT_ENVIRONMENT = { GIT_OPTIONAL_LOCKS: "0", GIT_NO_LAZY_FETCH: "1", GIT_TERMINAL_PROMPT: "0" } as const;

export function runGit(cwd: string, args: readonly string[], options: RunGitOptions = {}): GitResult {
  const result = spawnSync(gitExecutable(), [...SAFE_CONFIG, "-C", cwd, ...args], {
    encoding: "utf8",
    timeout: DEFAULT_TIMEOUT_MS,
    ...options,
    env: { ...process.env, ...GIT_ENVIRONMENT },
  });
  return { status: result.status, stdout: result.stdout ?? "", stderr: result.stderr ?? "" };
}

import { spawn, spawnSync } from "node:child_process";

export function gitProcess(cwd: string, args: readonly string[], env: NodeJS.ProcessEnv) {
  return spawn(gitExecutable(), [...SAFE_CONFIG, "-C", cwd, ...args], { env, stdio: ["ignore", "pipe", "pipe"] });
}

export function gitSync(cwd: string, args: readonly string[], environment: NodeJS.ProcessEnv) {
  return spawnSync(gitExecutable(), [...SAFE_CONFIG, "-C", cwd, ...args], { encoding: "utf8", env: environment });
}

import { gitExecutable, GitUnavailableError, gitText, runGit } from "../git.js";

export function lookupCheckout(workspace: string): CheckoutContext | undefined {
  try {
    gitExecutable();
  } catch (error) {
    if (error instanceof GitUnavailableError) return undefined;
    throw error;
  }
  const top = gitText(workspace, ["rev-parse", "--show-toplevel"]);
  const list = runGit(workspace, ["worktree", "list", "--porcelain", "-z"]);
  return top === undefined ? undefined : { top, worktrees: list.stdout };
}

import { runGit } from "../engine/git.js";

async function claudeLocalDirectory(workspaceDir: string, context: Context): Promise<string> {
  // rev-parse rejects non-repositories/bare repositories; Git also enforces safe.directory.
  if (runGit(workspaceDir, ["rev-parse", "--show-toplevel"]).status !== 0) return workspaceDir;
  const { stdout } = runGit(workspaceDir, ["worktree", "list", "--porcelain", "-z"]);
  return stdout;
}

export const RISKY_COMMANDS: ReadonlyArray<{ label: string; commands: readonly string[]; test: RegExp }> = [
  { label: "force push", commands: ["git"], test: /^git\s+push\b.*\s(?:--force(?:\s|=|$))/u },
  { label: "hard reset", commands: ["git"], test: /^git\s+reset\b.*\s--hard(?:\s|$)/u },
];

export function risky(command: string, words: readonly string[]): boolean {
  return words.includes("git") && RISKY_COMMANDS.some(entry => entry.test.test(command));
}

import { spawn } from "node:child_process";
import { existsSync } from "node:fs";
import { gitExecutable, GitUnavailableError } from "../engine/git.js";

function gitStatus(): { found: boolean; looked?: readonly string[] } {
  try {
    gitExecutable();
    return { found: true };
  } catch (error) {
    if (error instanceof GitUnavailableError) return { found: false, looked: error.looked };
    throw error;
  }
}

export function digitsOnly(command: string, digits: string): void {
  spawn(command, [digits], { stdio: "inherit" });
  existsSync("/usr/local/bin/git");
}

import { spawnSync } from "node:child_process";

const WORKTREE_LINE = /^worktree (.+)$/u;

export function firstWorktree(listing: string): string | undefined {
  return WORKTREE_LINE.exec(listing)?.[1];
}

export function xcrunGit(developerDir: string): string {
  return spawnSync(`${developerDir}/usr/bin/xcrun`, ["--find", "git"], { encoding: "utf8", env: { PATH: "/usr/bin:/bin" } }).stdout.trim();
}

import { spawnSync } from "node:child_process";

const GITHUB_CLI = "/opt/homebrew/bin/gh";

export function pullRequestUrl(root: string): string {
  return spawnSync(GITHUB_CLI, ["pr", "view", "--json", "url"], { cwd: root, encoding: "utf8" }).stdout.trim();
}

const HEAD_LINE = /^([0-9a-f]{40}) (.+)$/u;

export function headOf(gitOutput: string): string | undefined {
  return HEAD_LINE.exec(gitOutput)?.[1];
}

import { existsSync } from "node:fs";
import { join } from "node:path";

function findExecutable(name: string, path: string): string | undefined {
  return path.split(":").map(dir => join(dir, name)).find(existsSync);
}

export function gitShadowedOnPath(path: string): boolean {
  return findExecutable("git", path) !== undefined;
}

import { gitExecutable, GitUnavailableError } from "../engine/git.js";

export function gitLine(): string {
  try {
    const path = gitExecutable();
    return `Git: ${path}`;
  } catch (error) {
    if (error instanceof GitUnavailableError) return "Git: not found";
    throw error;
  }
}

import { runGit } from "../engine/git.js";

export function changed(root: string, against: string): string {
  return runGit(root, ["diff", "--name-only", "--no-renames", "--relative", "--diff-filter=ACMRTUXB", "-z", against, "--"]).stdout;
}

import { runGit } from "../engine/git.js";

export const head = (root: string) => runGit(root, ["log", "-1", "--format=%H"]).stdout.trim();
export const files = (root: string) => runGit(root, ["ls-files", "-z", "--", "diff"]).stdout;
export const ACTIONS = ["setup", "status", "diff"] as const;
